def geometry_plausible(element, anion, d_shortest,
                       fraction=None,
                       valence=None, cn=None):
    """
    True if the shortest cation-anion contact is credible against Shannon radii.

    Returns (is_plausible, expected_distance, ratio). If no radius can be
    found, returns (None, nan, nan) rather than guessing.

    v1.8.9: the cation radius is taken at the site's own valence and
    coordination number via get_ionic_radius_fractional(). The previous
    SHANNON_CN6 lookup was fixed at six-coordinate and blind to valence,
    which overstated the expected contact for every tetrahedral site by
    7-8% and biased them towards failing. SHANNON_CN6 remains as the
    fallback for combinations absent from the tabulation.
    """
    # v2.0.37: the threshold comes from radii_contact_threshold, the same
    # fitted function core_geometry_plausible uses, so this reported column and
    # the one that gates a tier can no longer disagree. An explicit `fraction`
    # still wins, for a caller that wants to ask a different question on
    # purpose.
    if fraction is None:
        fraction = radii_contact_threshold(cn)
    r_c = None
    if valence is not None and cn:
        try:
            v = float(valence)
            if v == v:                     # not NaN
                r_c, _src = get_ionic_radius_fractional(element, v, int(cn))
        except (TypeError, ValueError):
            r_c = None
    if r_c is None:
        r_c = SHANNON_CN6.get(element)
    r_a = ANION_RADIUS.get(anion)
    if r_c is None or r_a is None or not d_shortest:
        return None, float('nan'), float('nan')
    expected = r_c + r_a
    ratio = d_shortest / expected

    if ratio >= fraction:
        return True, expected, ratio

    # Failing. Only an explicitly configured advisory band may withhold that
    # verdict, and never below its floor. Contrast the old behaviour, which
    # withheld it for every A-site failure however severe.
    if WEAK_CATION_ADVISORY_FLOOR is not None:
        _lewis = None
        try:
            if valence is not None and cn:
                _lewis = abs(float(valence)) / float(cn)
        except (TypeError, ValueError, ZeroDivisionError):
            _lewis = None
        if (_lewis is not None and _lewis <= WEAK_CATION_LEWIS_MAX
                and ratio >= WEAK_CATION_ADVISORY_FLOOR):
            return None, expected, ratio

    return False, expected, ratio


