# --- CIF loading (mirrors Eir's cleaning: UTF-8 repair + HR symop fix) --------

import re as _re, tempfile as _tempfile

def load_structure(path):
    """
    Read a CIF into a gemmi SmallStructure.

    v2.0.3: uses clean_cif_for_gemmi rather than a local copy of it. CELL 7
    carried its own _clean_cif_text, a hand-copy of the CELL 1 cleaner that had
    since diverged from it. Every coordination-quality column in the output was
    therefore computed from an unrepaired parse, and nine sites across five
    structures came back NaN with nothing said, because the only report of the
    failure sits behind `verbose` in the caller.
    """
    txt = clean_cif_for_gemmi(path)
    if txt is None:
        raise RuntimeError(f'could not clean {os.path.basename(path)}')
    with _tempfile.NamedTemporaryFile('w', suffix='.cif', delete=False,
                                      encoding='utf-8') as t:
        t.write(txt); tp = t.name
    try:
        st = gemmi.make_small_structure_from_block(
            gemmi.cif.read(tp).sole_block())
    finally:
        try:
            os.unlink(tp)
        except OSError:
            pass
    if st.spacegroup is None:
        m = (_re.search(r'_space_group_IT_number\s+(\d+)', txt) or
             _re.search(r'_symmetry_Int_Tables_number\s+(\d+)', txt))
        if m:
            st.spacegroup = gemmi.find_spacegroup_by_number(int(m.group(1)))
    return st


def _expand(st, rmax=NEIGHBOUR_SEARCH_MAX):
    # v2.0.35: wrapped, and the block sized from the cutoff instead of being
    # fixed at one image. cn and cn_relative are both built from this list, so
    # when it lost a neighbour the two agreed with each other and the
    # cross-check could not fire: on ICSD 23164 both said 3.
    pts = []
    _n = image_range(st.cell, rmax)
    _rng = range(-_n, _n + 1)
    for s in st.sites:
        for op in st.spacegroup.operations():
            f = wrap_into_cell(op.apply_to_xyz(
                [s.fract.x, s.fract.y, s.fract.z]))
            for i in _rng:
                for j in _rng:
                    for k in _rng:
                        p = st.cell.orthogonalize(
                            gemmi.Fractional(f[0]+i, f[1]+j, f[2]+k))
                        pts.append((s.element.name, p.x, p.y, p.z))
    return pts


def neighbour_distances(cif_path, rmax=NEIGHBOUR_SEARCH_MAX, dedup_tol=0.02):
    """
    Per asymmetric-unit cation site, the sorted distances to each anion species.

    Neighbours are deduplicated by Cartesian position, because the symmetry
    expansion generates the same physical atom once per operation that maps
    onto it. Without this every distance is counted several times and both CN
    and ECoN come out as multiples of the true value.

    Returns {(frac_coords, element): {anion_element: [distances...]}}
    """
    st = load_structure(cif_path)
    if st.spacegroup is None:
        raise RuntimeError("no space group")
    pts = _expand(st, rmax)
    els = np.array([p[0] for p in pts])
    P = np.array([[p[1], p[2], p[3]] for p in pts])

    out = {}
    for s in st.sites:
        el = s.element.name
        if el in ANION_RADIUS:
            continue
        o = site_centre(st.cell, s)
        p0 = np.array([o.x, o.y, o.z])
        d = np.linalg.norm(P - p0, axis=1)
        m = np.where((d > 0.01) & (d <= rmax))[0]
        m = m[np.argsort(d[m])]

        per_anion = {}
        kept_pos = []
        for idx in m:
            ael = els[idx]
            if ael not in ANION_RADIUS:
                continue
            pos = P[idx]
            if any(np.linalg.norm(pos - kp) <= dedup_tol for kp in kept_pos):
                continue
            kept_pos.append(pos)
            per_anion.setdefault(ael, []).append(float(d[idx]))
        for a in per_anion:
            per_anion[a].sort()

        fkey = (round(s.fract.x, 4), round(s.fract.y, 4), round(s.fract.z, 4))
        out[(fkey, el)] = per_anion
    return out



# ============================================================================
# POSITIONAL UNCERTAINTY  (v2.0.30)
# ============================================================================
#
# The esds a CIF deposits are statements about how well the structure is
# known, and every bond length here is a function of them. See
# Eir_2_0_29_provenance.md for why this replaces the intuition that older
# determinations are less trustworthy: measured over 3291 structures, the
# publication year does not predict the index anywhere after 1950, and
# neither does the coordinate precision on its own. What precision does give
# is an error bar, which is a different and more useful thing than a flag.

# The standard deviation of a uniform distribution of width w is w/sqrt(12).
# A coordinate written to n decimal places with no esd is known only to lie
# in a rounding interval of width 10^-n, so that is its sigma. Half the
# interval, 10^-n/2, is the BOUND, which is 1.73x larger and is not
# comparable with a stated esd. Measured on ICSD 252227: the same A site
# reads +/- 0.016 v.u. from its stated esd and would read +/- 0.23 or +/-
# 0.41 v.u. if its oxygen had been deposited to two decimal places under the
# two conventions respectively.
ROUNDING_SD_FACTOR = 1.0 / _math_sqrt12()   # 0.288675, = 1/sqrt(12)


def parse_sigma(token):
    """
    (value, sigma, source) for one deposited number, or None if not a number.

    Built on parse_value_with_error from CELL 2 rather than beside it: that
    function already knows every form ICSD writes a number in, including the
    leading-dot forms that cost ICSD 420711 its shift test in 2.0.2.
    """
    if token is None:
        return None
    t = str(token).strip()
    if t in ('', '.', '?'):
        return None
    v, e = parse_value_with_error(t)
    if v is None:
        return None
    if e is not None:
        return (v, e, 'stated')
    dp = len(t.split('.')[1]) if '.' in t else 0
    return (v, (10.0 ** (-dp)) * ROUNDING_SD_FACTOR, 'rounding')


def coordinate_sigmas(cif_text):
    """
    {site_label: {'x': (value, sigma, source), 'y': ..., 'z': ...}}

    Read from the deposited text, not from gemmi's parse, because gemmi
    discards the parenthesised esd and that is the entire quantity wanted.
    """
    lines = cif_text.splitlines()
    out, i = {}, 0
    while i < len(lines):
        if lines[i].strip() != 'loop_':
            i += 1
            continue
        j, cols = i + 1, []
        while j < len(lines) and lines[j].strip().startswith('_'):
            cols.append(lines[j].strip().split()[0])
            j += 1
        try:
            i_lab = cols.index('_atom_site_label')
            ix = cols.index('_atom_site_fract_x')
            iy = cols.index('_atom_site_fract_y')
            iz = cols.index('_atom_site_fract_z')
        except ValueError:
            i = j
            continue
        while (j < len(lines) and lines[j].strip()
               and not lines[j].strip().startswith(('_', 'loop_', '#'))):
            f = lines[j].split()
            if len(f) == len(cols):
                rec = {}
                for axis, k in (('x', ix), ('y', iy), ('z', iz)):
                    p = parse_sigma(f[k])
                    if p is not None:
                        rec[axis] = p
                if len(rec) == 3:
                    out[f[i_lab]] = rec
            j += 1
        i = j
    return out


def _rref(A, tol=1e-9):
    """Reduced row echelon form, and the pivot column of each surviving row."""
    A = np.array(A, dtype=float)
    rows, cols = A.shape
    pivots, r = [], 0
    for c in range(cols):
        if r >= rows:
            break
        p = r + int(np.argmax(np.abs(A[r:, c])))
        if abs(A[p, c]) < tol:
            continue
        A[[r, p]] = A[[p, r]]
        A[r] = A[r] / A[r, c]
        for i in range(rows):
            if i != r and abs(A[i, c]) > tol:
                A[i] = A[i] - A[i, c] * A[r]
        pivots.append(c)
        r += 1
    return A[:r], pivots


def free_parameters(spacegroup, frac, sigmas_xyz, tol=1e-4):
    """
    The independent refined parameters of one site, from its site symmetry.

    A CIF deposits three coordinates for every atom, but a site on a special
    position has fewer than three refined parameters and the coordinates it
    deposits are not independent. O1 in a normal spinel is on 32e at (u,u,u):
    ONE number written down three times. Combining the three in quadrature
    understates the uncertainty on the A-site bond valence sum by sqrt(3),
    and no numerical derivative over the coordinates can detect that, because
    it makes the same assumption.

    Returns [(w, sigma, pivot_axis, source), ...] where w is the vector of
    d(fractional coordinate)/d(parameter).
    """
    f = np.asarray(frac, dtype=float)
    fixed = []
    for op in spacegroup.operations():
        W = np.array(op.rot, dtype=float) / op.DEN
        w = np.array(op.tran, dtype=float) / op.DEN
        d = W @ f + w - f
        if np.allclose(d - np.round(d), 0.0, atol=tol):
            fixed.append(W)
    if not fixed:
        fixed = [np.eye(3)]              # the identity always fixes a site
    P = sum(fixed) / len(fixed)          # projector onto the free subspace
    basis, pivots = _rref(P.T)           # rows of P.T are the columns of P
    out = []
    for row, k in zip(basis, pivots):
        axis = 'xyz'[k]
        if axis in sigmas_xyz:
            out.append((row.copy(), sigmas_xyz[axis][1], axis,
                        sigmas_xyz[axis][2]))
    return out


def _orth_matrix(cell):
    """
    The three cell vectors in Cartesian coordinates, as columns.

    Written out rather than taken from gemmi so the convention is visible and
    so the derivative below can be checked against it.
    """
    a, b, c = cell[0], cell[1], cell[2]
    al, be, ga = (math.radians(x) for x in cell[3:6])
    ca, cb, cg, sg = (math.cos(al), math.cos(be), math.cos(ga), math.sin(ga))
    cz2 = 1.0 - cb * cb - ((ca - cb * cg) / sg) ** 2
    return np.array([[a, b * cg, c * cb],
                     [0.0, b * sg, c * (ca - cb * cg) / sg],
                     [0.0, 0.0, c * math.sqrt(max(cz2, 0.0))]], dtype=float)




# v2.0.38: THE CELL IS A REFINED PARAMETER TOO.
#
# Until 2.0.38 `params` held coordinates only and the cell was a constant, so
# a structure with every atom on a fixed special position reported sigma = 0
# and the 'fixed' source. For a rock salt that is a false zero: d(M-X) = a/2,
# and a is refined. Measured on 88 of 503 WAGII rock salts, the cell esd alone
# gives a median sigma(GII) of 0.0014 v.u. and a 90th percentile of 0.0116,
# with 3% above PGRM_IMPRECISE_SIGMA - which gate M9 could not see while the
# number was zero.
CELL_PARAM_NAMES = ('a', 'b', 'c', 'alpha', 'beta', 'gamma')

# Central-difference step. Lengths are in angstroms and angles in degrees, and
# _orth_matrix is smooth in both, so 1e-6 sits far above the noise floor of a
# double and far below any curvature that matters. Checked against the
# analytic diag(1,0,0) for an orthogonal cell in check C of the edit script.
_CELL_DERIV_H = 1.0e-6


def cell_sigmas(cif_text):
    """
    {'a': (value, sigma, source), ...} for the six cell parameters.

    Read from the deposited text for the same reason coordinate_sigmas does:
    gemmi discards the parenthesised esd, and that is the entire quantity
    wanted. parse_sigma supplies the rounding fallback, so a cell written
    `4.1` with no esd is not silently treated as exact.
    """
    out = {}
    for name in CELL_PARAM_NAMES:
        key = '_cell_length_' + name if name in ('a', 'b', 'c') \
              else '_cell_angle_' + name
        m = _re.search(r'^\s*' + key + r'\s+(\S+)', cif_text, _re.M)
        if not m:
            continue
        p = parse_sigma(m.group(1))
        if p is not None:
            out[name] = p
    return out


def _cell_free_groups(spacegroup):
    """
    Which cell parameters are independent, as groups that move together.

    A cubic cell deposits a, b and c with one esd between them because there
    is one refined length. Moving the three independently and combining in
    quadrature is the same sqrt(n) understatement free_parameters exists to
    prevent on a (u,u,u) site, so the constrained lengths are returned as ONE
    group and differentiated as one parameter.

    Returns [(name, (member, ...)), ...]. Angles appear only where the system
    leaves them free; elsewhere they are fixed by symmetry at 90 or 120 and
    carry no refined uncertainty whatever the file says.
    """
    n = spacegroup.number if spacegroup is not None else 0
    if 195 <= n <= 230:                       # cubic
        return [('a', ('a', 'b', 'c'))]
    if 75 <= n <= 194:                        # tetragonal, trigonal, hexagonal
        return [('a', ('a', 'b')), ('c', ('c',))]
    if 16 <= n <= 74:                         # orthorhombic
        return [('a', ('a',)), ('b', ('b',)), ('c', ('c',))]
    if 3 <= n <= 15:                          # monoclinic, unique axis b
        return [('a', ('a',)), ('b', ('b',)), ('c', ('c',)),
                ('beta', ('beta',))]
    return [(k, (k,)) for k in CELL_PARAM_NAMES]      # triclinic, or unknown


def _dorth_matrix(cell, members):
    """
    d(_orth_matrix)/d(parameter), moving every member of a constrained group
    together, by central difference on _orth_matrix itself.

    Differentiated numerically rather than by hand because _orth_matrix is
    six-parameter triclinic and a hand-written dM/dp for it is a page of
    trigonometry that nothing would ever check. The central difference is
    checked against the analytic answer for the orthogonal case instead,
    where dM/da is exactly diag(1, 0, 0).
    """
    idx = [CELL_PARAM_NAMES.index(m) for m in members]
    hi, lo = list(cell), list(cell)
    for i in idx:
        hi[i] += _CELL_DERIV_H
        lo[i] -= _CELL_DERIV_H
    return (_orth_matrix(hi) - _orth_matrix(lo)) / (2.0 * _CELL_DERIV_H)


def free_cell_parameters(spacegroup, cell, sigmas_cell):
    """
    [(name, sigma, source, dM/dp), ...] for the independent cell parameters.

    A STATED ESD BEATS A ROUNDING INTERVAL within a constrained group, and
    that is not a preference, it is what the two numbers mean. ICSD 56538
    deposits

        _cell_length_a  5.5463(2)
        _cell_length_b  5.5463
        _cell_length_c  5.5463

    which is one refined length written three times, once with its esd and
    twice as a bare echo. The bare copies are not a claim that the number is
    known only to four decimal places; they carry no information at all. So
    the stated members decide the sigma and the source, and the rounding
    fallback applies only where no member states anything. Taking max() over
    all three instead would have called this group 'mixed' and, on a file
    whose echoes were rounded more coarsely than the stated value, would have
    inflated the sigma by two orders of magnitude.

    Where more than one member states an esd they should agree - the file
    refined the quantity once - and where they do not, the largest is the
    conservative reading.
    """
    out = []
    for name, members in _cell_free_groups(spacegroup):
        present = [m for m in members if m in sigmas_cell]
        if not present:
            continue
        stated = [m for m in present if sigmas_cell[m][2] == 'stated']
        use = stated or present
        sd = max(sigmas_cell[m][1] for m in use)
        if not sd:
            continue
        srcs = {sigmas_cell[m][2] for m in use}
        src = srcs.pop() if len(srcs) == 1 else 'mixed'
        out.append((name, sd, src, _dorth_matrix(cell, members)))
    return out


def positional_uncertainty(cif_path, rmax=NEIGHBOUR_SEARCH_MAX,
                           dedup_tol=0.02):
    """
    Per cation site, every anion contact with its derivative with respect to
    each independent refined parameter in the structure.

    Deliberately the same expansion, the same rmax, the same dedup tolerance
    and the same site key as neighbour_distances above, so a contact that
    appears in one appears in the other. Only the bookkeeping differs: this
    one keeps the rotation part of the operation that produced each image,
    which is what the derivative needs and what _expand throws away.

        X    = position of the neighbour minus position of the site
        R    = |X|,   u = X / R
        dR/d(site coords)      = -u . M
        dR/d(neighbour coords) = +u . (M W)

    The translation parts never appear because they are constants.

    Returns (params, table):
      params = [(label, axis, sigma, source, w), ...] where w is
               d(fractional coordinates)/d(parameter)
      table  = {(fkey, element): {anion: [(R, dR/dp array), ...sorted]}}
    """
    st = load_structure(cif_path)
    if st.spacegroup is None:
        raise RuntimeError("no space group")
    txt = clean_cif_for_gemmi(cif_path)
    if txt is None:
        raise RuntimeError("could not clean CIF")
    sig = coordinate_sigmas(txt)
    sigc = cell_sigmas(txt)

    cell = (st.cell.a, st.cell.b, st.cell.c,
            st.cell.alpha, st.cell.beta, st.cell.gamma)
    M = _orth_matrix(cell)
    cellpar = free_cell_parameters(st.spacegroup, cell, sigc)

    params, pslice = [], {}
    for s in st.sites:
        if s.label not in sig:
            continue
        fp = free_parameters(st.spacegroup,
                             (s.fract.x, s.fract.y, s.fract.z), sig[s.label])
        if not fp:
            continue
        pslice[s.label] = (len(params), [w for w, _, _, _ in fp])
        for _w, sd, axis, src in fp:
            # w is kept: it is the Wyckoff relation between this parameter and
            # the three deposited coordinates, (1,1,1) for a spinel 32e oxygen.
            # Without it a caller cannot move the parameter, only a coordinate,
            # and those differ by a factor of 3 on exactly that site.
            params.append((s.label, axis, sd, src, tuple(round(float(x), 10)
                                                         for x in _w)))
    # v2.0.38: the cell parameters are appended AFTER the coordinates, so
    # every existing index into `params` is unchanged and sigma_from_gradient,
    # _rms_sigma and max_coord_sigma need no edit. The 5-tuple shape is kept;
    # the w slot is None because a cell parameter has no Wyckoff relation to
    # a fractional coordinate, and nothing downstream reads it.
    cellbase = len(params)
    for _nm, _sd, _src, _dM in cellpar:
        params.append(('<cell>', _nm, _sd, _src, None))
    npar = len(params)

    images = []
    for s in st.sites:
        f = np.array([s.fract.x, s.fract.y, s.fract.z], dtype=float)
        for op in st.spacegroup.operations():
            W = np.array(op.rot, dtype=float) / op.DEN
            w = np.array(op.tran, dtype=float) / op.DEN
            ft = W @ f + w
            for i in (-1, 0, 1):
                for j in (-1, 0, 1):
                    for k in (-1, 0, 1):
                        _fim = ft + np.array([i, j, k], dtype=float)
                        # v2.0.38: the fractional image is kept beside the
                        # Cartesian one. dR/d(cell) needs the fractional
                        # offset, and recovering it by inverting M would
                        # reintroduce the rounding this avoids.
                        images.append((s.label, s.element.name, W,
                                       M @ _fim, _fim))

    out = {}
    for s in st.sites:
        el = s.element.name
        if el in ANION_RADIUS:
            continue
        p0 = M @ np.array([s.fract.x, s.fract.y, s.fract.z], dtype=float)
        cand = []
        for lab2, el2, W2, pos, fim in images:
            if el2 not in ANION_RADIUS:
                continue
            X = pos - p0
            R = float(np.linalg.norm(X))
            if 0.01 < R <= rmax:
                cand.append((R, X, lab2, W2, pos, fim))
        cand.sort(key=lambda t: t[0])

        per_anion, kept = {}, []
        for R, X, lab2, W2, pos, fim2 in cand:
            if any(np.linalg.norm(pos - kp) <= dedup_tol for kp in kept):
                continue
            kept.append(pos)
            g = np.zeros(npar, dtype=float)
            uvec = X / R
            # v2.0.38: X = M . (f_neighbour - f_site), so with the fractional
            # offset held fixed, dX/dp = (dM/dp) . df and dR/dp = u . dX/dp.
            # Accumulated into the same gradient vector as the coordinates so
            # the quadrature stays in one place.
            _df = fim2 - np.array([s.fract.x, s.fract.y, s.fract.z],
                                  dtype=float)
            for _n2, (_nm, _sd, _src, _dM) in enumerate(cellpar):
                g[cellbase + _n2] += float(uvec @ (_dM @ _df))
            if s.label in pslice:
                base, ws = pslice[s.label]
                d1 = -(uvec @ M)
                for n, w in enumerate(ws):
                    g[base + n] += float(d1 @ w)
            if lab2 in pslice:
                base, ws = pslice[lab2]
                d2 = uvec @ (M @ W2)
                for n, w in enumerate(ws):
                    g[base + n] += float(d2 @ w)
            _ael = None
            for _s2 in st.sites:
                if _s2.label == lab2:
                    _ael = _s2.element.name
                    break
            per_anion.setdefault(_ael, []).append((R, g))

        fkey = (round(s.fract.x, 4), round(s.fract.y, 4), round(s.fract.z, 4))
        out[(fkey, el)] = per_anion
    return params, out


def bvs_gradient(entry, r0, b, cn):
    """
    d(bond valence sum)/d(parameter) over the first `cn` contacts, and the
    sum itself.

    The derivatives are accumulated over the bonds BEFORE anything is
    squared, which is what keeps symmetry-equivalent bonds correlated.

        dS/dp = sum_j (-S_j / b) dR_j/dp
    """
    if not entry or not r0 or not b:
        return None, None
    bl = sorted(entry, key=lambda t: t[0])
    if cn and cn == cn:
        bl = bl[:int(cn)]
    if not bl:
        return None, None
    total = 0.0
    grad = np.zeros(len(bl[0][1]), dtype=float)
    for R, dR in bl:
        s = math.exp((r0 - R) / b)
        total += s
        grad += (-s / b) * dR
    return total, grad


def sigma_from_gradient(grad, params):
    """
    Quadrature over the INDEPENDENT parameters only, plus which kind of
    number the uncertainty came from.
    """
    if grad is None:
        return None, None
    var, srcs = 0.0, set()
    for n, (_lab, _axis, sd, src, _w) in enumerate(params):
        if sd and grad[n]:
            var += (grad[n] * sd) ** 2
            srcs.add(src)
    if not srcs:
        # v2.0.38: reaching here now means neither a coordinate NOR a cell
        # parameter moves this bond length, which is a far stronger statement
        # than it was in 2.0.37 and should be rare. Before 2.0.38 every
        # fixed-position structure landed here and reported a false zero.
        return 0.0, 'fixed'
    return math.sqrt(var), (srcs.pop() if len(srcs) == 1 else 'mixed')


def _parse_coords(s):
    """
    Fractional coordinates from a CSV cell. None if unparseable.

    Returning None makes the row fail to match its site, so a broadened
    except here loses a site silently rather than loudly.
    """
    try:
        t = tuple(float(x) for x in str(s).strip('() ').split(','))
        return tuple(round(v, 4) for v in t)
    except (TypeError, ValueError, AttributeError):
        return None


def _distances_for_row(table, coords_str, element, tol=0.02):
    """Match a CSV row to its site by fractional coordinates, not by element. Returns per-anion mapping"""
    target = _parse_coords(coords_str)
    cands = [(k, v) for k, v in table.items() if k[1] == element]
    if not cands:
        return {}
    if target is not None:
        best, bestd = None, 1e9
        for (fkey, _el), per_anion in cands:
            d = sum(min(abs(a - b), 1 - abs(a - b)) ** 2
                    for a, b in zip(fkey, target)) ** 0.5
            if d < bestd:
                best, bestd = per_anion, d
        if best is not None and bestd <= tol:
            return best
    return cands[0][1]


# --- diagnosis ---------------------------------------------------------------

# observational_diagnosis was removed at v2.0.13. It derived the same labels
# by recomputing the anion side from an aggregate deviation, and was
# superseded by observational_diagnosis_from_flags, which takes the verified
# per-structure flag instead. Two functions producing the same column from
# different inputs is how a producer and its consumer drift apart.

def observational_diagnosis_from_flags(cation_gii, anion_balances,
                                       gii_tol=CATION_GII_TOLERANCE):
    """
    Same labels, but takes the verified per-structure `anion_balances` flag
    from chunk 1 rather than recomputing the anion side from an aggregate.
    """
    if cation_gii is None or (isinstance(cation_gii, float) and np.isnan(cation_gii)):
        return 'insufficient_data'
    if anion_balances is None or (isinstance(anion_balances, float) and np.isnan(anion_balances)):
        return 'insufficient_data'
    an_ok = str(anion_balances).strip().lower() in ('true', '1', 'yes')
    cat_off = cation_gii > gii_tol
    if not cat_off and an_ok:
        return 'cation_and_anion_agree'
    if cat_off and an_ok:
        return 'cation_only_deviates'
    if cat_off and not an_ok:
        return 'both_deviate'
    return 'anion_only_deviates'


# --- GII including anion sites, and the refined diagnosis --------------------

def gii_all_sites(cation_deviations, anion_deviations):
    """
    RMS deviation over cations AND anions (the Salinas-Sanchez / Brown form).

    Kept separate from Eir's `gii`, which is cation-only. Pooling the anions
    dilutes the index in exactly the parameter-offset cases the cation/anion
    comparison is designed to detect, so the two are reported side by side
    rather than one replacing the other.
    """
    d = [x for x in list(cation_deviations) + list(anion_deviations)
         if x is not None and not (isinstance(x, float) and np.isnan(x))]
    if not d:
        return float('nan')
    return float(np.sqrt(np.mean(np.square(d))))


SHELL_CORRECTION = True
SHELL_CORRECTION_TOL = 0.002      # v.u., the GII reconstruction check


def _rms_index(dev, weights, keys):
    """RMS of `dev` over `keys`, weighted. The published GII/WAGII form."""
    w = weights.astype(float)
    num = (w * dev.astype(float) ** 2).groupby(keys).sum()
    den = w.groupby(keys).sum()
    return np.sqrt(num / den.replace(0, np.nan))


def _site_averaged(df):
    """
    The site-averaged deviation family, over the dataframe.

    CELL 2 forms this once, from results['sites'], BEFORE the shell correction
    rewrites any bond valence sum. Expressed here as well so it can be rebuilt
    afterwards from the final sums. The two definitions must agree, and that is
    checked at run time in apply_shell_correction rather than asserted in a
    comment.

    One deviation per crystallographic POSITION: the occupancy-weighted mean of
    the per-species sums, minus the occupancy-weighted mean of their expected
    valences. A position is dropped entirely if any species on it lacks a sum,
    which is what CELL 2 does - not filtered species by species, which would
    silently change the weights.

    The index over positions is an UNWEIGHTED root mean square. That is
    deliberate and is not the wagii weighting: wagii weights sites by
    occupancy, this one has already used occupancy inside each position and
    treats the positions themselves as equals.

    Returns (site_bvs, site_expected, site_deviation) aligned to df's rows, and
    the per-filename index as a Series.
    """
    b = pd.to_numeric(df['bvs'], errors='coerce')
    v = pd.to_numeric(df['valence'], errors='coerce').abs()
    # CELL 2's `x or 1.0`: a missing occupancy is full. A refined 0.0 stays 0.0
    # and makes its position weightless, which drops it.
    occ = pd.to_numeric(df['occupancy'], errors='coerce').fillna(1.0)

    # Grouped on the two columns themselves rather than on a joined string
    # key. A separator is a guess about what cannot appear in a filename or a
    # coordinate, and this file has already paid for one guess too many.
    fn = df['filename'].astype(str)
    cd = df['coords'].astype(str)
    # grouped on the two ARRAYS, not on a MultiIndex object: groupby(index)
    # groups by the tuples and returns a flat Index of them, so a later
    # groupby(level=0) silently does nothing and every position becomes its
    # own structure. Grouping on [fn, cd] gives a real MultiIndex.
    bad = (b.isna() | v.isna()).groupby([fn, cd]).transform('any')
    ok = ~bad

    den = occ.where(ok).groupby([fn, cd]).sum().replace(0, np.nan)
    site_b = (occ * b).where(ok).groupby([fn, cd]).sum() / den
    site_v = (occ * v).where(ok).groupby([fn, cd]).sum() / den
    site_d = site_b - site_v
    assert isinstance(site_d.index, pd.MultiIndex), (
        'the position index is not a MultiIndex, so the per-structure '
        'root mean square below would be taken over single positions')

    good = site_d.dropna()
    idx = (good ** 2).groupby(level=0).mean().pow(0.5)

    pair = pd.MultiIndex.from_arrays([fn, cd])
    take = lambda s: pd.Series(s.reindex(pair).to_numpy(), index=df.index)
    return take(site_b), take(site_v), take(site_d), idx


def _index_inputs(df):
    """The sites that contribute to the instability index, and their weights.

    Mirrors the exclusions calculate_gii applies in CELL 2 - a site refined to
    no atom, and a site whose shortest contact is not a bond - so that the
    index rebuilt here is the SAME quantity rather than a similar one.
    """
    b = pd.to_numeric(df['bvs'], errors='coerce')
    v = pd.to_numeric(df['valence'], errors='coerce').abs()
    occ = pd.to_numeric(df['occupancy'], errors='coerce').fillna(1.0)
    mb = pd.to_numeric(df.get('min_bond_length'), errors='coerce')
    keep = (b.notna() & v.notna() & (v > 0) & (occ != 0.0)
            & ~(mb < CATION_ANION_ABSOLUTE_MIN))
    return b, v, occ, keep


def apply_shell_correction(df):
    """Item 4.2. Replace a shell that has reached into the second sphere.

    See the module docstring of the edit that introduced this for the three
    broader rules that were measured and rejected. In short: every simpler
    version wrecks the perovskite A site, which presents identically and is
    not the same phenomenon.

    Applied where all three hold:
      - cn_fault says shell_reaches_outer_sphere
      - Gagne directly measured the boundary for that ion configuration
      - an adaptive sum exists to put in its place

    Measured on 3291 structures: 188 sites corrected, 183 structures improve,
    3 worsen, and only 12 of the 1895 perovskite sites are touched.
    """
    if not SHELL_CORRECTION:
        return df
    need = {'cn_fault', 'bv_boundary_source', 'bvs_bv_adaptive',
            'cn_bv_adaptive', 'bvs', 'valence', 'filename'}
    if not need <= set(df.columns):
        return df
    df = df.copy()

    trig = (df['cn_fault'].astype(str).eq('shell_reaches_outer_sphere')
            & df['bv_boundary_source'].astype(str).str.startswith('measured_n')
            & pd.to_numeric(df['bvs_bv_adaptive'], errors='coerce').notna()
            & pd.to_numeric(df['cn_bv_adaptive'], errors='coerce').notna())
    df['shell_corrected'] = trig

    # BEFORE changing anything: prove this code can rebuild CELL 2's index from
    # the table. If it cannot, the corrected index would be a second, different
    # quantity wearing the same column name - which is the recurring fault of
    # this project and is not worth a shell fix.
    b, v, occ, keep = _index_inputs(df)
    keys = df.loc[keep, 'filename']
    dev = (b - v).abs()
    gii_rebuilt = _rms_index(dev[keep], pd.Series(1.0, index=keys.index), keys)
    exported = df.groupby('filename')['gii'].first()
    check = pd.concat([exported.rename('a'), gii_rebuilt.rename('b')],
                      axis=1).dropna()
    if len(check):
        untouched = ~check.index.isin(df.loc[trig, 'filename'].unique())
        worst = (check['a'] - check['b']).abs()[untouched].max()
        if worst == worst and worst > SHELL_CORRECTION_TOL:
            raise AssertionError(
                f'apply_shell_correction cannot reproduce the exported GII '
                f'from the per-site table (worst disagreement {worst:.4f} '
                f'v.u. on a structure it does not touch). The rebuilt index '
                f'is not the same quantity as the exported one; fix that '
                f'before correcting any shell.')

    n = int(trig.sum())
    if not n:
        print('  Shell correction: no site met the trigger.')
        return df

    for src, dst in (('cn', 'cn_uncorrected'), ('bvs', 'bvs_uncorrected')):
        df[dst] = df[src]
    for fn, gcol in (('gii', 'gii_uncorrected'), ('wagii', 'wagii_uncorrected')):
        if fn in df.columns:
            df[gcol] = df[fn]

    df.loc[trig, 'cn'] = pd.to_numeric(df.loc[trig, 'cn_bv_adaptive'],
                                       errors='coerce')
    df.loc[trig, 'bvs'] = pd.to_numeric(df.loc[trig, 'bvs_bv_adaptive'],
                                        errors='coerce')
    if 'bvs_percent_diff' in df.columns:
        _v = pd.to_numeric(df.loc[trig, 'valence'], errors='coerce').abs()
        _b = pd.to_numeric(df.loc[trig, 'bvs'], errors='coerce')
        df.loc[trig, 'bvs_percent_diff'] = ((_b - _v) / _v * 100).round(2)

    # v2.0.23 (item 2): THE DISTANCE SCREEN IS DERIVED FROM cn, SO IT MOVES
    # WITH cn. This is a fault I introduced in 2.0.21 and did not test for.
    #
    # bvs_distance_ratio is min_bond_length / (R0 - b ln(|v| / cn)). 2.0.21
    # rewrote cn, bvs, gii and wagii here and left the ratio exactly as CELL 2
    # computed it, at the PRE-correction cn. The exported cn and the cn behind
    # the ratio then disagreed, with no column saying so.
    #
    # ICSD 210888, Li1, measured on the 2.0.22 spinel run:
    #
    #     exported cn            4
    #     min_bond_length        1.7893 A
    #     bvs_distance_ratio     0.6296   -> d_ideal 2.842 A -> cn 16
    #     Li(1+)-O Gagne 2015    r0 1.062, b 0.642
    #     d_ideal at cn = 4      1.952 A  -> ratio 0.917, threshold 0.792
    #
    # The site passes at its own coordination number and was being condemned
    # at a coordination number the correction had already replaced. 174 of the
    # 540 failing spinel sites were in that state and 173 pass once recomputed.
    #
    # The guard I wrote in 2.0.21 reconstructed GII and would have raised if
    # THAT disagreed. It checked the columns I changed and was silent about
    # the column I left behind, which is the whole lesson: a correction that
    # rewrites one half of a derived pair must rewrite the other half or
    # refuse to run.
    _need_ratio = {'bvs_distance_ratio', 'bvs_distance_threshold',
                   'bvs_geometry_plausible', 'min_bond_length', 'element',
                   'valence'}
    if _need_ratio <= set(df.columns):
        for _c, _u in (
                ('bvs_distance_ratio', 'bvs_distance_ratio_uncorrected'),
                ('bvs_distance_threshold',
                 'bvs_distance_threshold_uncorrected'),
                ('bvs_geometry_plausible',
                 'bvs_geometry_plausible_uncorrected')):
            df[_u] = df[_c]

        _anion_of = (df['bvs_distance_anion']
                     if 'bvs_distance_anion' in df.columns
                     else pd.Series('O', index=df.index))
        _bvpar = {}

        def _params(el, val, an):
            # One cached lookup, so the loop and the check cannot diverge.
            _k = (str(el), float(val), str(an))
            if _k not in _bvpar:
                try:
                    _bvpar[_k] = get_bv_parameters_fractional(el, val, an)
                except Exception:
                    _bvpar[_k] = None
            return _bvpar[_k]

        def _d_ideal(el, val, cn, an):
            _p = _params(el, val, an)
            if not _p or _p[0] is None or _p[1] in (None, 0):
                return float('nan')
            if not (cn == cn and cn > 0 and val == val and val != 0):
                return float('nan')
            _x = _p[0] - _p[1] * np.log(abs(float(val)) / float(cn))
            return _x if _x > 0 else float('nan')

        _redone = 0
        for _i in df.index[trig]:
            _cn2 = pd.to_numeric(df.at[_i, 'cn'], errors='coerce')
            _v2 = pd.to_numeric(df.at[_i, 'valence'], errors='coerce')
            _d2 = pd.to_numeric(df.at[_i, 'min_bond_length'], errors='coerce')
            _di = _d_ideal(df.at[_i, 'element'], _v2, _cn2, _anion_of.at[_i])
            if not (_di == _di and _d2 == _d2 and _d2 > 0):
                continue
            _r2 = _d2 / _di
            _t2 = bvs_distance_threshold(_cn2)
            df.at[_i, 'bvs_distance_ratio'] = round(_r2, 4)
            df.at[_i, 'bvs_distance_threshold'] = round(_t2, 4)
            df.at[_i, 'bvs_geometry_plausible'] = bool(_r2 >= _t2)
            _redone += 1

        # The check 2.0.21 lacked, over EVERY site rather than the ones just
        # rewritten: re-checking only the corrected rows would be checking
        # this function's own arithmetic. Every ratio in the table must be the
        # one its own exported cn implies.
        _worst_r, _worst_at = 0.0, None
        for _i in df.index:
            _r = pd.to_numeric(df.at[_i, 'bvs_distance_ratio'],
                               errors='coerce')
            _d2 = pd.to_numeric(df.at[_i, 'min_bond_length'], errors='coerce')
            if not (_r == _r and _d2 == _d2 and _d2 > 0):
                continue
            _di = _d_ideal(df.at[_i, 'element'],
                           pd.to_numeric(df.at[_i, 'valence'],
                                         errors='coerce'),
                           pd.to_numeric(df.at[_i, 'cn'], errors='coerce'),
                           _anion_of.at[_i])
            if _di != _di:
                continue
            _e = abs(_r - _d2 / _di)
            if _e > _worst_r:
                _worst_r, _worst_at = _e, _i
        if _worst_r > 0.005:
            raise AssertionError(
                f'bvs_distance_ratio does not match the cn it is exported '
                f'beside (worst {_worst_r:.4f} at row {_worst_at}, '
                f'{df.at[_worst_at, "element"]} in '
                f'{df.at[_worst_at, "filename"]}). The ratio is '
                f'min_bond_length / (R0 - b ln(|v|/cn)); if cn is rewritten '
                f'anywhere, the ratio must be rewritten with it.')
        print(f'    bvs_distance_ratio recomputed on {_redone} corrected '
              f'site(s); every site now agrees with its own cn to '
              f'{_worst_r:.4f}.')

    b, v, occ, keep = _index_inputs(df)
    keys = df.loc[keep, 'filename']
    dev = (b - v).abs()
    new_gii = _rms_index(dev[keep], pd.Series(1.0, index=keys.index), keys)
    new_wag = _rms_index(dev[keep], occ[keep], keys)
    # Written back ONLY for the structures that actually contain a corrected
    # site. Mapping the rebuilt index over everything would replace 3000
    # exported values with freshly computed ones that differ in the fourth
    # decimal - the rounding residual - and 222 structures would appear to
    # move when 173 were touched. A recomputation is not an improvement if it
    # perturbs the rows it had no business visiting.
    _hit = set(df.loc[trig, 'filename'].unique())
    _m = df['filename'].isin(_hit)
    df.loc[_m, 'gii'] = df.loc[_m, 'filename'].map(new_gii).round(4)
    df.loc[_m, 'wagii'] = df.loc[_m, 'filename'].map(new_wag).round(4)

    # v2.0.32: THE SITE-AVERAGED FAMILY, which was left behind.
    #
    # CELL 2 forms site_bvs_averaged, site_expected_averaged,
    # site_deviation_averaged and gii_site_averaged from the sums it had at the
    # time. The correction above rewrites those sums, so for every structure it
    # touches, all four were stale - and gii_site_averaged is what
    # gii_recommended names for roughly half the corpus, and what the
    # ACCEPT_HOMOVALENT and ACCEPT_HETEROVALENT tiers tell a reader to quote.
    #
    # Measured before the fix, over 3291 structures: 178 disagreed with the
    # same definition applied to the final sums, median 0.062 and worst 0.235
    # v.u., and EVERY ONE of them was shell-corrected. No untouched structure
    # moved by more than 0.0001.
    #
    # Found by the uncertainty guard in CELL 7, which refused to attach a sigma
    # to an index it could not reproduce.
    _sb, _se, _sd, _sa = _site_averaged(df)

    # THE LIVE CHECK. On the structures this correction did NOT touch, the
    # definition here must reproduce the one CELL 2 exported. Checked on the
    # real corpus on every run, because two places forming the same quantity
    # from different inputs is precisely how this drift happened.
    if 'gii_site_averaged' in df.columns:
        _un = df.loc[~_m]
        if len(_un):
            _ex = pd.to_numeric(_un.groupby('filename')['gii_site_averaged']
                                .first(), errors='coerce')
            _rb = _sa.reindex(_ex.index)
            _off = (_ex - _rb).abs().dropna()
            if len(_off) and float(_off.max()) > SHELL_CORRECTION_TOL:
                _bad = _off.idxmax()
                raise AssertionError(
                    f'_site_averaged does not reproduce CELL 2 on a structure '
                    f'the shell correction never touched: {_bad}, exported '
                    f'{_ex[_bad]:.4f} against {_rb[_bad]:.4f}. The two '
                    f'definitions have drifted and neither number can be '
                    f'trusted until they agree.')
            _wr = float(_off.max()) if len(_off) else 0.0
        else:
            _wr = 0.0
        df['gii_site_averaged_uncorrected'] = df['gii_site_averaged']
        for _c, _new in (('site_bvs_averaged', _sb),
                         ('site_expected_averaged', _se),
                         ('site_deviation_averaged', _sd)):
            if _c in df.columns:
                df.loc[_m, _c] = _new[_m].round(4)
        _n_sa = int((pd.to_numeric(df['gii_site_averaged'], errors='coerce')
                     - df['filename'].map(_sa)).abs()
                    .gt(0.0005).groupby(df['filename']).any().sum())
        df.loc[_m, 'gii_site_averaged'] = (
            df.loc[_m, 'filename'].map(_sa).round(4))
        print(f"    gii_site_averaged rebuilt on the corrected sums: "
              f"{_n_sa} structure(s) moved. On the "
              f"{df.loc[~_m, 'filename'].nunique()} structure(s) the "
              f"correction did not touch it reproduces CELL 2 to {_wr:.5f}.")

    # v2.0.33: AND THE COPY OF IT THAT THE TIERS TELL A READER TO QUOTE.
    #
    # gii_recommended_value is taken in CELL 2 by recommended_index(), before
    # this correction runs, and was never refreshed. Measured on the 2.0.32
    # outputs: 186 of 3291 structures carried a value that did not equal the
    # index their own gii_recommended column named, median 0.062 and worst
    # 0.235 v.u., every one of them shell-corrected. 39 of those were wrong
    # before this week's work, from gii alone.
    #
    # ONLY THE VALUE IS REBUILT. recommended_index() chooses on topology -
    # whether a position carries two elements, and has_antisite_disorder - and
    # the correction changes neither, so the NAME it returned is still right.
    # Re-deriving the selection here would be a second copy of a rule with no
    # reason to move.
    if set(['gii_recommended', 'gii_recommended_value']) <= set(df.columns):
        _rec = df['gii_recommended'].astype(str)
        _look = pd.Series(np.nan, index=df.index, dtype=float)
        for _nm in ('gii', 'wagii', 'gii_site_averaged'):
            if _nm in df.columns:
                _sel = _rec.eq(_nm)
                if _sel.any():
                    _look.loc[_sel] = pd.to_numeric(df.loc[_sel, _nm],
                                                    errors='coerce')
        _had = pd.to_numeric(df['gii_recommended_value'], errors='coerce')

        # THE GUARD, same shape as the one above: on structures this correction
        # did not touch, the lookup must already agree with the exported copy.
        # If it does not, the two have drifted for a reason that is not the
        # shell correction and neither can be trusted.
        _chk = (_look - _had).abs()[~_m].dropna()
        if len(_chk) and float(_chk.max()) > SHELL_CORRECTION_TOL:
            _at = _chk.idxmax()
            raise AssertionError(
                'gii_recommended_value disagrees with the index it names on '
                + str(df.at[_at, 'filename']) + ', which the shell correction '
                'never touched: ' + format(_had[_at], '.4f') + ' against '
                + format(_look[_at], '.4f') + ' for ' + str(_rec[_at]) + '.')
        _rv_worst = float(_chk.max()) if len(_chk) else 0.0
        _rv_moved = int((_look - _had).abs()[_m].gt(0.0005)
                        .groupby(df.loc[_m, 'filename']).any().sum())
        df['gii_recommended_value_uncorrected'] = df['gii_recommended_value']
        df.loc[_m, 'gii_recommended_value'] = _look[_m].round(4)
        print('    gii_recommended_value refreshed from the index it names: '
              + str(_rv_moved) + ' structure(s) moved. On the untouched ones '
              'it already agreed to ' + format(_rv_worst, '.5f') + '.')

    _ns = df.loc[trig, 'filename'].nunique()
    _moved = int((pd.to_numeric(df['gii'], errors='coerce')
                  - pd.to_numeric(df['gii_uncorrected'], errors='coerce'))
                 .abs().gt(1e-4).groupby(df['filename']).any().sum())
    print(f"\n  SHELL CORRECTION (item 4.2): {n} site(s) in {_ns} structure(s).")
    print(f"    The shell had reached into the second coordination sphere and "
          f"Gagne measured that boundary directly, so the adaptive shell "
          f"replaces it.")
    print(f"    gii and wagii recomputed; {_moved} structure(s) moved. The "
          f"originals are in cn_uncorrected, bvs_uncorrected, "
          f"gii_uncorrected and wagii_uncorrected,")
    print(f"    and shell_corrected marks every site. Set "
          f"SHELL_CORRECTION = False to disable.")
    return df


def refine_diagnosis(label, any_distorted):
    """
    Split `both_deviate` on whether any cation polyhedron is distorted.

    A regular polyhedron that still deviates points at the structure or the
    data. A distorted one is usually real: a Jahn-Teller active ion has one
    averaged geometry standing in for an elongated environment, and BVS
    handles that badly. Everything else passes through unchanged.
    """
    if label != 'both_deviate':
        return label
    if any_distorted is None:
        return label
    return 'both_deviate_distorted' if any_distorted else 'both_deviate_regular'


# The order the diagnosis labels are reported in: agreement first, then the
# cases that point at the parameters, then those that point at the structure.
# Defined once here and read by the dataset summary in CELL 14. Until v2.0.13
# this list existed twice - here, unread, and again in CELL 14 as
# DIAGNOSIS_ORDER_REPORT, byte-identical.
DIAGNOSIS_ORDER = [
    'cation_and_anion_agree',
    'cation_only_deviates',
    'both_deviate_regular',
    'both_deviate_distorted',
    'both_deviate',
    'anion_only_deviates',
    'insufficient_data',
]


# --- main entry point --------------------------------------------------------

def _require_cn_fault():
    """
    `cn_fault` lives in CELL 2 from Eir 2.0.2 onwards. Fail here, with the
    remedy, rather than three lines later with a bare NameError, or worse,
    silently falling back to a one-sided test that reports no faults at all.
    """
    if 'cn_fault' not in globals():
        raise NameError(
            'cn_fault is not defined. It moved to CELL 2 in Eir 2.0.2; '
            're-run the main cell (CELL 2) before this one. Running with the '
            'old one-sided test would report zero amputated coordination '
            'shells rather than none existing.')


def _eir_neighbours(path):
    """(neighbour table, error string or None) for one CIF. v2.0.28.

    The try/except is here rather than at the call site so that a structure
    which cannot be read costs its own coordination columns and nothing
    else, exactly as before - and so the message reaches the parent as data
    instead of being printed inside a worker process where nobody sees it.
    """
    try:
        return neighbour_distances(path), None
    except Exception as e:
        return {}, f'{type(e).__name__}: {e}'


def _eir_uncertainty(path):
    """(params, table, error string or None) for one CIF. v2.0.30.

    A direct reference to positional_uncertainty, never globals()[...]:
    cloudpickle ships only the globals a function statically references, and
    a dynamic lookup here is what cost 2.0.28 its entire anion side.

    Same split of the exception handling as its neighbour: a structure that
    cannot be read costs its own uncertainty columns and nothing else.
    """
    try:
        p, t = positional_uncertainty(path)
        return p, t, None
    except Exception as e:
        return [], {}, f'{type(e).__name__}: {e}'


def _eir_anion_side(args):
    """(anion deviations, note or None) for one structure. v2.0.28.

    Same split of the exception handling as the loop it came out of:
    NameError, AttributeError and TypeError are a defect in the anion engine
    and are re-raised; anything else is a property of the CIF, and costs the
    anion side of one index rather than the run.
    """
    path, vals = args[0], args[1]
    # v2.0.44: the void-guard limits, when the job carries them.
    limits = args[2] if len(args) > 2 else None
    try:
        # v2.0.29: a DIRECT reference, not globals()['calculate_anion_bvs'].
        #
        # cloudpickle ships the globals a function statically references. A
        # dynamic lookup is invisible to it, so in 2.0.28 the function was
        # never sent to the workers, every call raised KeyError, and the
        # except below reported 'anion side unavailable' 1881 times while
        # the run still claimed success. gii_all_sites silently became the
        # cation-only index: median 0.5484 against gii's 0.5474.
        #
        # The membership test in the caller - if 'calculate_anion_bvs' in
        # globals() - is untouched, and is right: it runs in the parent.
        return [a.get('anion_deviation')
                for a in calculate_anion_bvs(path, vals,
                                             shell_limits=limits)], None
    except (NameError, AttributeError, TypeError):
        raise
    except Exception as e:
        return [], f'{type(e).__name__}: {e}'


def add_coordination_quality(batch_csv_path, cif_directory,
                             output_csv_path=None, verbose=True):
    """
    Post-process an Eir batch CSV: add ECoN, coordination-quality and
    geometry-plausibility columns, and replace bvs_diagnosis with the
    observational labels.

    Leaves the existing pipeline untouched; reads the CSV, writes a new one.
    """
    _require_cn_fault()
    _t_pp = _time.perf_counter()
    df = pd.read_csv(batch_csv_path)
    _n_struct = df['filename'].nunique()
    if verbose:
        # v2.0.24: a header in the batch feed's shape, so the two halves of a
        # run look like one program rather than two.
        print('=' * 78)
        print(f'EIR POST-PROCESSING   v{EIR_VERSION}')
        print('=' * 78)
        print(f'  reading     {os.path.basename(batch_csv_path)}')
        print(f'  rows        {len(df)}   one per crystallographic cation site')
        print(f'  structures  {_n_struct}')
        print('=' * 78)

    cache = {}
    # v2.0.24: the two expensive loops in this function both run once per
    # STRUCTURE and both used to run in silence. This one re-reads and
    # symmetry-expands every CIF; the gii_all_sites loop below recomputes the
    # anion side. Between them they are nearly all of the wall clock.
    _tick_cq = StageTicker('coordination quality: re-reading and expanding '
                           'each CIF', _n_struct, enabled=verbose)
    _tick_cq.start()

    # v2.0.28: filled UP FRONT, in file order, serially or across processes.
    # It used to fill lazily inside the per-site loop below, which is the
    # same work in the same order and could not be handed to a pool. The
    # loop is otherwise untouched: it still reads `cache` and still has its
    # own miss handler, which now never fires.
    _paths, _seen_p = [], set()
    for _fn0 in df['filename']:
        if isinstance(_fn0, str):
            _p0 = os.path.join(cif_directory, _fn0)
            if _p0 not in _seen_p:
                _seen_p.add(_p0)
                _paths.append(_p0)
    try:
        import psutil as _ps0
        _rss0 = _ps0.Process().memory_info().rss
    except Exception:
        _rss0 = None
    for _p0, (_tbl0, _err0) in zip(
            _paths, _measured_map(
                _paths, _eir_neighbours,
                announce=(lambda a, b, c, d, e: _parallel_banner(
                    lambda s: print(s, flush=True), 'coordination quality',
                    a, b, c, d, e, unit='structure')) if verbose else None,
                weight=lambda p: os.path.getsize(str(p)))):
        if _err0:
            # The message the lazy version printed, to the character, so the
            # log of a 2.0.28 run can be diffed against a 2.0.27 one.
            print(f"  ! coordination quality unavailable for "
                  f"{os.path.basename(_p0)}: {_err0}")
        cache[_p0] = _tbl0
        _tick_cq.tick()

    # v2.0.30: the uncertainty pass, through the same scheduler, with its own
    # cache. Separate from the neighbour pass on purpose: it can fail, or be
    # switched off, without touching a single existing column.
    ucache = {}
    if PROPAGATE_UNCERTAINTY:
        _tick_pu = StageTicker('positional uncertainty: differentiating '
                               'every bond', len(_paths), enabled=verbose)
        _tick_pu.start()
        for _p1, (_par1, _tab1, _err1) in zip(
                _paths, _measured_map(
                    _paths, _eir_uncertainty,
                    announce=(lambda a, b, c, d, e: _parallel_banner(
                        lambda s: print(s, flush=True), 'positional uncertainty',
                        a, b, c, d, e, unit='structure')) if verbose else None,
                    weight=lambda p: os.path.getsize(str(p)))):
            if _err1:
                print(f"  ! uncertainty unavailable for "
                      f"{os.path.basename(_p1)}: {_err1}")
            ucache[_p1] = (_par1, _tab1)
            _tick_pu.tick()
        _tick_pu.close()

    econ_v, ratio_v, dav_v, cnrel_v = [], [], [], []
    plaus_v, expd_v, dratio_v, regular_v = [], [], [], []
    canion_v = []
    bvssig_v, bvssrc_v, nfree_v = [], [], []
    _grad_by_row = {}

    for _, row in df.iterrows():
        fn = row.get('filename')
        el = row.get('element')
        path = os.path.join(cif_directory, fn) if isinstance(fn, str) else None

        if path and path not in cache:
            # v2.0.28: the cache is filled above, so this is now a safety net
            # for a path the pre-pass did not see rather than the normal
            # route. Kept, and kept printing, because a silent miss here
            # would cost every coordination column for that structure and
            # the NaNs are indistinguishable from a site that genuinely has
            # no neighbours (v2.0.3).
            cache[path], _e_late = _eir_neighbours(path)
            if _e_late:
                print(f"  ! coordination quality unavailable for {fn}: "
                      f"{_e_late}")

        table = cache.get(path, {})
        per_anion = _distances_for_row(table, row.get('coords'), el)
        ds = [d for dl in per_anion.values() for d in dl]

        if not ds:
            econ_v.append(np.nan); ratio_v.append(np.nan)
            dav_v.append(np.nan);  cnrel_v.append(np.nan)
            plaus_v.append(None);  expd_v.append(np.nan)
            dratio_v.append(np.nan); regular_v.append(None)
            canion_v.append(None)
            bvssig_v.append(np.nan); bvssrc_v.append(None)
            nfree_v.append(np.nan)
            continue

        cn_r = cn_relative(ds)
        shell = sorted(ds)[:cn_r] if cn_r else sorted(ds)
        e, dav = effective_coordination_number(shell)

        # v1.8.9: test each anion species against its own radius and keep the
        # worst contact. Assuming oxygen made the screen inoperative for
        # sulfides, where a normal M-S bond looks long against r(O).
        plaus, expd, dr, contact_anion = None, np.nan, np.nan, None
        for _ael, _dl in per_anion.items():
            _p, _ex, _r = geometry_plausible(el, _ael, min(_dl),
                                             valence=row.get('valence'), cn=cn_r)
            if _r == _r and (dr != dr or _r < dr):
                plaus, expd, dr, contact_anion = _p, _ex, _r, _ael

        econ_v.append(round(e, 4))
        cnrel_v.append(cn_r)
        ratio_v.append(round(e / cn_r, 4) if cn_r else np.nan)
        dav_v.append(round(dav, 4))
        plaus_v.append(plaus)
        expd_v.append(round(expd, 3) if expd == expd else np.nan)
        dratio_v.append(round(dr, 4) if dr == dr else np.nan)
        regular_v.append(bool(e / cn_r >= ECON_REGULAR_MIN) if cn_r else None)
        canion_v.append(contact_anion)

        # v2.0.30: the uncertainty on this site's bond valence sum, over the
        # SAME shell the sum itself used - row['cn'], the canonical bond
        # valence coordination number, not cn_r, which is the independent
        # distance-based estimate. R0 and b come from
        # get_bv_parameters_fractional, the same function that assigned them
        # when the sum was computed, so there is one definition of them.
        _sd = _src = None
        _nfree = np.nan
        if PROPAGATE_UNCERTAINTY and path in ucache:
            _upar, _utab = ucache[path]
            _nfree = len(_upar)
            _uent = _distances_for_row(_utab, row.get('coords'), el)
            _lig = contact_anion or (sorted(_uent)[0] if _uent else None)
            if _uent and _lig in _uent:
                _r0u, _bu = get_bv_parameters_fractional(
                    el, row.get('valence'), _lig)
                _tot, _gr = bvs_gradient(_uent.get(_lig), _r0u, _bu,
                                         row.get('cn'))
                if _gr is not None:
                    _sd, _src = sigma_from_gradient(_gr, _upar)
                    _grad_by_row[len(bvssig_v)] = (fn, _gr, _upar)
        bvssig_v.append(np.nan if _sd is None else round(_sd, 5))
        bvssrc_v.append(_src)
        nfree_v.append(_nfree)

    _tick_cq.close(
        f', {len(cache)} CIF(s) read'
        + ('' if _rss0 is None else
           f', cache holding about '
           f'{max(0, _ps0.Process().memory_info().rss - _rss0) / 2**20:.0f} MB'))

    df['econ'] = econ_v
    df['econ_d_av'] = dav_v
    df['cn_relative'] = cnrel_v
    df['econ_cn_ratio'] = ratio_v
    # v2.0.2: symmetric fault detection, from CELL 2. The closure that used
    # to live here tested only the over-counting direction. geo_cn is passed
    # as a second opinion where the batch CSV carries it.
    _geo = (df['geo_cn'] if 'geo_cn' in df.columns else pd.Series([None] * len(df)))
    # v2.0.20: the spread between the shortest and the mean bond, which is what
    # separates a duplicated image (no spread) from a shell that has reached
    # into the second coordination sphere (a large one). Without it cn_fault
    # can only say that the ratio is an integer, which is what it used to
    # mistake for a diagnosis.
    if {'avg_bond_length', 'min_bond_length'} <= set(df.columns):
        _spread = (pd.to_numeric(df['avg_bond_length'], errors='coerce')
                   - pd.to_numeric(df['min_bond_length'], errors='coerce'))
    else:
        # v2.0.46: a float column. [None] * n is an object column, whose
        # round() raises TypeError, and a batch whose table had no bond
        # lengths at all stopped here.
        _spread = pd.Series([float('nan')] * len(df), index=df.index, dtype=float)
    df['cn_shell_spread'] = _spread.round(4)
    df['cn_fault'] = [cn_fault(c, r, g, spread=s) for c, r, g, s in
                      zip(df['cn'], df['cn_relative'], _geo, _spread)]

    df = apply_shell_correction(df)

    # The most generous independent estimate, and how far the bond valence
    # coordination number falls short of it. Written out so a downstream
    # filter does not have to recompute which estimate won.
    _refs = [pd.to_numeric(df[c], errors='coerce')
             for c in ('cn_relative', 'geo_cn') if c in df.columns]
    if _refs:
        df['cn_reference'] = pd.concat(_refs, axis=1).max(axis=1)
        df['cn_disagreement'] = (df['cn_reference']
                                 - pd.to_numeric(df['cn'], errors='coerce'))
    _amp = df['cn_fault'].astype(str).str.startswith('cn_below_shell')
    if _amp.any():
        _n_s = df.loc[_amp, 'filename'].nunique()
        print(f"\n  ! {int(_amp.sum())} sites in {_n_s} structures have a bond "
              f"valence sum computed over an amputated coordination shell.")
        print(f"    The gap analysis cut the shell short of every independent "
              f"estimate, so the sum is low for a reason that is not chemistry.")
        print(f"    Filter on cn_fault before quoting any deviation or "
              f"validation rate. Reported, not repaired: cn_gap_shell holds "
              f"the gap answer and cn the canonical one, so the "
              f"disagreement is visible per site.")
    df['polyhedron_regular'] = regular_v
    df['shortest_contact_ratio'] = dratio_v
    df['expected_contact'] = expd_v
    df['geometry_plausible'] = plaus_v
    df['contact_anion'] = canion_v
    df['bvs_sigma'] = bvssig_v
    df['bvs_sigma_source'] = bvssrc_v
    df['n_free_params'] = nfree_v

    # v2.0.30: the structure-level uncertainty, and the guard that makes it
    # safe to quote.
    #
    # gii is a root-mean-square of the site deviations, so
    #
    #     d(gii)/dp = (1 / (N gii)) sum_i (bvs_i - v_i) d(bvs_i)/dp
    #
    # and the parameters are combined in quadrature only after that sum, for
    # the same reason the bonds were.
    #
    # THE GUARD. A sigma attached to the wrong index is precisely the class of
    # fault this project keeps finding in other people's data, and the site
    # set used here is reconstructed rather than inherited. So gii_sigma is
    # withheld unless this cell can reproduce the structure's own exported gii
    # from the same sites to 0.005 v.u. Where it cannot, gii_sigma is null and
    # gii_sigma_basis says why, rather than a number being reported against an
    # index it does not belong to.
    if PROPAGATE_UNCERTAINTY and _grad_by_row:
        # _grad_by_row is keyed by POSITION in df, because it was filled from
        # df.iterrows(), which walks in positional order. Everything below
        # reads df positionally for the same reason.
        _fn_a = df['filename'].tolist()
        _bvs_a = pd.to_numeric(df['bvs'], errors='coerce').tolist()
        _val_a = pd.to_numeric(df['valence'], errors='coerce').tolist()
        _gii_a = pd.to_numeric(df['gii'], errors='coerce').tolist()
        _sa_a = (pd.to_numeric(df['gii_site_averaged'], errors='coerce').tolist()
                 if 'gii_site_averaged' in df.columns else [np.nan] * len(df))
        _occ_a = (pd.to_numeric(df['occupancy'], errors='coerce').fillna(1.0)
                  .tolist() if 'occupancy' in df.columns else [1.0] * len(df))
        _crd_a = (df['coords'].astype(str).tolist()
                  if 'coords' in df.columns else [''] * len(df))
        _rec_a = (df['gii_recommended'].astype(str).tolist()
                  if 'gii_recommended' in df.columns else [''] * len(df))
        # v2.0.37: wagii per row, so its sigma is checked against the number
        # Eir exported rather than against a rebuild of it.
        _wag_a = (pd.to_numeric(df['wagii'], errors='coerce').tolist()
                  if 'wagii' in df.columns else [np.nan] * len(df))

        def _rms_sigma(devs, grads, pars, ref, name, weights=None):
            """
            Sigma on sqrt(sum(w dev^2) / sum(w)), given d(dev)/dp per term.

            One definition, called for gii, for gii_site_averaged and - since
            v2.0.37 - for wagii. They differ only in how the deviations are
            formed and how they are weighted, and writing the arithmetic three
            times is how this project acquired most of the faults it has spent
            the week finding.

                index = sqrt(S / W),  S = sum w dev^2,  W = sum w
                d(index)/dp = (1 / (index W)) sum_k w_k dev_k d(dev_k)/dp

            With every weight 1 that is the unweighted form this held before,
            which is why gii and gii_site_averaged are unchanged by the
            generalisation rather than merely expected to be.

            THE GUARD. The index reconstructed here must match the one Eir
            exported to 0.005 v.u. If it does not, the sites this pass could
            differentiate are not the sites Eir summed over, and a sigma
            reported against that index would belong to a different number.
            For wagii the same guard also tests the WEIGHTING: wrong weights
            rebuild a different number and the basis says so.
            """
            if not devs or pars is None or ref is None or ref != ref:
                return np.nan, 'no usable sites'
            _w = [1.0] * len(devs) if weights is None else [float(x) for x in weights]
            _W = float(sum(_w))
            if _W <= 0:
                return np.nan, 'no usable sites'
            _here = float(np.sqrt(sum(_wk * _dv ** 2
                                      for _wk, _dv in zip(_w, devs)) / _W))
            if abs(_here - ref) > 0.005:
                return np.nan, f'could not reproduce {name}'
            if _here <= 0:
                return 0.0, name
            _G = np.zeros(len(pars), dtype=float)
            for _wk, _dv, _gr in zip(_w, devs, grads):
                _G = _G + _wk * _dv * _gr
            _G = _G / (_W * _here)
            _var = 0.0
            for _k in range(len(pars)):
                _sd1 = pars[_k][2]
                if _sd1:
                    _var += (_G[_k] * _sd1) ** 2
            return round(math.sqrt(_var), 5), name

        _by_struct = {}
        for _pos in _grad_by_row:
            _by_struct.setdefault(_grad_by_row[_pos][0], []).append(_pos)

        _gs, _gb, _sas, _rs, _rb, _mx = {}, {}, {}, {}, {}, {}
        _mxs = {}          # v2.0.41: stated / rounding / mixed
        _ws, _wb = {}, {}
        for _fn1, _poss in _by_struct.items():
            _poss = sorted(_poss)
            _pars = _grad_by_row[_poss[0]][2]

            # --- gii: one deviation per site
            _dev, _grads, _giiref = [], [], None
            for _p in _poss:
                _d1 = _bvs_a[_p] - _val_a[_p]
                if _d1 != _d1:
                    continue
                _dev.append(_d1)
                _grads.append(_grad_by_row[_p][1])
                if _giiref is None and _gii_a[_p] == _gii_a[_p]:
                    _giiref = _gii_a[_p]
            _gs[_fn1], _gb[_fn1] = _rms_sigma(_dev, _grads, _pars, _giiref, 'gii')

            # --- wagii: the same deviations, weighted by occupancy, which is
            #     how CELL 2 forms it: sqrt(sum(occ dev^2) / sum(occ))
            _wdev, _wgrads, _wwt, _wagref = [], [], [], None
            for _p in _poss:
                _d1 = _bvs_a[_p] - _val_a[_p]
                if _d1 != _d1:
                    continue
                _wdev.append(_d1)
                _wgrads.append(_grad_by_row[_p][1])
                _wwt.append(_occ_a[_p])
                if _wagref is None and _wag_a[_p] == _wag_a[_p]:
                    _wagref = _wag_a[_p]
            _ws[_fn1], _wb[_fn1] = _rms_sigma(_wdev, _wgrads, _pars, _wagref,
                                              'wagii', weights=_wwt)

            # --- gii_site_averaged: one deviation per crystallographic
            #     POSITION, occupancy weighted, exactly as CELL 2 forms it
            _grp = {}
            for _p in _poss:
                if _bvs_a[_p] != _bvs_a[_p] or _val_a[_p] != _val_a[_p]:
                    continue
                _grp.setdefault(_crd_a[_p], []).append(_p)
            _sdev, _sgrads, _saref = [], [], None
            for _key, _mem in _grp.items():
                _w = sum(_occ_a[_p] for _p in _mem)
                if not _w:
                    continue
                _b = sum(_occ_a[_p] * _bvs_a[_p] for _p in _mem) / _w
                _e = sum(_occ_a[_p] * abs(_val_a[_p]) for _p in _mem) / _w
                _gv = np.zeros(len(_pars), dtype=float)
                for _p in _mem:
                    _gv = _gv + _occ_a[_p] * _grad_by_row[_p][1]
                _sdev.append(_b - _e)
                _sgrads.append(_gv / _w)
            for _p in _poss:
                if _saref is None and _sa_a[_p] == _sa_a[_p]:
                    _saref = _sa_a[_p]
            _sas[_fn1] = _rms_sigma(_sdev, _sgrads, _pars, _saref,
                                    'gii_site_averaged')[0]

            # --- the one that matches gii_recommended
            _rec = _rec_a[_poss[0]]
            if _rec == 'gii':
                _rs[_fn1], _rb[_fn1] = _gs[_fn1], _gb[_fn1]
            elif _rec == 'gii_site_averaged':
                _rs[_fn1] = _sas[_fn1]
                _rb[_fn1] = ('gii_site_averaged' if _sas[_fn1] == _sas[_fn1]
                             else 'could not reproduce gii_site_averaged')
            elif _rec == 'wagii':
                # v2.0.37: wagii is an occupancy-weighted RMS of the same site
                # deviations, so the generalised helper does apply to it and
                # the withheld sigma is withheld no longer.
                _rs[_fn1], _rb[_fn1] = _ws[_fn1], _wb[_fn1]
            else:
                _rs[_fn1], _rb[_fn1] = np.nan, f'{_rec} has no sigma'

            # --- the largest esd the depositor put on any coordinate
            # v2.0.38: cell parameters live in _pars too now, and this
            # column is named for coordinates. Filter them out rather than
            # quietly changing what the column means.
            _cpar = [_p1 for _p1 in _pars if _p1[0] != '<cell>']
            _mx[_fn1] = round(max((_p1[2] for _p1 in _cpar),
                                  default=np.nan), 6)
            # v2.0.41: AND WHERE THE NUMBER CAME FROM.
            #
            # parse_sigma returns 'stated' for a value with an esd and
            # 'rounding' for one without, where the sigma is the width of the
            # rounding interval over sqrt(12). Both land in this column and
            # until now it read identically for the two. On the 1881 spinels
            # that is 1395 stated against 478 imputed, and the imputed ones
            # are not small: a free coordinate written as a bare `0` has no
            # decimal places, so its interval is the whole cell and its sigma
            # is 1/sqrt(12) = 0.2887 fractional, 2.4 A. Eight P4332 spinels
            # carry exactly that.
            #
            # Not corrected, because 1/sqrt(12) of the interval is the right
            # arithmetic for the model and the model is what is arguable -
            # a bare `0` on a free coordinate is a formatting convention, not
            # a statement that the atom could be anywhere. Made VISIBLE
            # instead, so a reader can see which of the two they have.
            _srcs = set(_p1[3] for _p1 in _cpar)
            _mxs[_fn1] = ('mixed' if len(_srcs) > 1
                          else (_srcs.pop() if _srcs else None))

        df['gii_sigma'] = df['filename'].map(_gs)
        df['gii_sigma_basis'] = df['filename'].map(_gb)
        df['gii_site_averaged_sigma'] = df['filename'].map(_sas)
        df['wagii_sigma'] = df['filename'].map(_ws)
        df['wagii_sigma_basis'] = df['filename'].map(_wb)
        df['gii_recommended_sigma'] = df['filename'].map(_rs)
        df['gii_recommended_sigma_basis'] = df['filename'].map(_rb)
        # v2.0.31: not a screen, a number. An esd above about 0.1 fractional
        # is not a refinement result. ICSD 236153 deposits 0.72(85), which is
        # 0.85 - seven angstroms in its own cell - while reporting the 41st
        # best GII of 938 perovskites.
        df['max_coord_sigma'] = df['filename'].map(_mx)
        df['max_coord_sigma_source'] = df['filename'].map(_mxs)
    else:
        df['gii_sigma'] = np.nan
        df['gii_sigma_basis'] = None
        df['wagii_sigma'] = np.nan
        df['wagii_sigma_basis'] = None
        df['gii_site_averaged_sigma'] = np.nan
        df['gii_recommended_sigma'] = np.nan
        df['gii_recommended_sigma_basis'] = None
        df['max_coord_sigma'] = np.nan
        df['max_coord_sigma_source'] = None

    # structure-level plausibility: one bad contact condemns the structure
    bad = (df.groupby('filename')['geometry_plausible']
             .apply(lambda s: (s == False).any()))
    df['structure_geometry_plausible'] = ~df['filename'].map(bad).fillna(False).astype(bool)

    # v2.0.2: the same roll-up for the core radii-ratio screen. Eir 2.0.2
    # exports structure_core_geometry_plausible directly; for a CSV written by
    # an earlier version the column is absent and core_geometry_plausible is
    # per SITE, so it is rolled up here on the same rule. Taking .first()
    # instead, as summarise_dataset did, reads whichever site happens to come
    # first and misses the failure whenever the bad site is not row one.
    if 'structure_core_geometry_plausible' not in df.columns:
        if 'core_geometry_plausible' in df.columns:
            _core = df['core_geometry_plausible']
            if _core.dtype == object:
                _core = _core.astype(str).str.lower().map(
                    {'true': True, '1': True, '1.0': True,
                     'false': False, '0': False, '0.0': False})
            _bad_core = (df.assign(_c=_core).groupby('filename')['_c']
                           .apply(lambda s: (s == False).any()))
            df['structure_core_geometry_plausible'] = ~df['filename'].map(
                _bad_core).fillna(False).astype(bool)
            _nf = int((~df.drop_duplicates('filename')
                       ['structure_core_geometry_plausible']).sum())
            print(f"  rolled up core_geometry_plausible from sites: "
                  f"{_nf} structures flagged on the radii-ratio screen")
        else:
            df['structure_core_geometry_plausible'] = None

    if 'gii' in df.columns and 'anion_balances' in df.columns:
        df['bvs_diagnosis'] = [
            observational_diagnosis_from_flags(g, b)
            for g, b in zip(df['gii'], df['anion_balances'])
        ]

    # refined diagnosis: split both_deviate on polyhedron regularity
    _dist = (df.groupby('filename')['polyhedron_regular']
               .apply(lambda s: (False in set(s.dropna().tolist()))
                      if s.notna().any() else None))
    df['bvs_diagnosis_detail'] = [
        refine_diagnosis(lab, _dist.get(fn))
        for lab, fn in zip(df['bvs_diagnosis'], df['filename'])
    ]

    # GII including anion sites, for literature comparability
    _gii_all = {}
    if 'calculate_anion_bvs' in globals():
        _tick_ga = StageTicker('gii_all_sites: bond valence on the anion side',
                               df['filename'].nunique(), enabled=verbose)
        _tick_ga.start()
        # v2.0.28: the valence dictionary is built here, per structure, and
        # only calculate_anion_bvs goes to the pool. Building it is cheap and
        # touches the frame, which does not belong in a worker.
        _ga_jobs = []
        for fn, g in df.groupby('filename'):
            path = os.path.join(cif_directory, fn)
            # v2.0.13: keyed by SITE LABEL as well as element. Keying it by
            # element alone gave every site of an element whichever valence
            # came last, so in Co3O4 the 8a Co(2+) and the 16d Co(3+) were
            # summed with one R0. This is the same fault as in
            # anion_bvs_for_structure, in a second path that calls
            # calculate_anion_bvs directly and so did not inherit that fix.
            # 147 of 1881 spinels carry an element at two valences.
            vals = {}
            for _, rr in g.iterrows():
                _v = rr.get('valence')
                if _v != _v:
                    continue
                if rr.get('site_label'):
                    vals[rr['site_label']] = _v
                if rr.get('element'):
                    vals.setdefault(rr['element'], _v)
            for _ael, _dv in DEFAULT_ANION_VALENCES.items():
                vals.setdefault(_ael, _dv)
            # v2.0.44: the same void-guard limits as anion_bvs_for_structure.
            _lims = None
            if 'shell_void_limit' in g.columns:
                _lims = {rr['site_label']: float(rr['shell_void_limit'])
                         for _, rr in g.iterrows()
                         if rr.get('site_label') and
                         pd.notna(rr.get('shell_void_limit'))} or None
            _ga_jobs.append((fn, path, vals, _lims, g))

        for (fn, path, vals, _lims, g), (adev, _note) in zip(
                _ga_jobs,
                _measured_map(
                    [(j[1], j[2], j[3]) for j in _ga_jobs], _eir_anion_side,
                    announce=(lambda a, b, c, d, e: _parallel_banner(
                        lambda s: print(s, flush=True), 'anion side',
                        a, b, c, d, e, unit='structure')) if verbose else None,
                    weight=lambda t: os.path.getsize(str(t[0])))):
            if _note:
                # gii_all_sites would otherwise be computed over the cations
                # alone and reported under a name that says it includes the
                # anions. Same message as before, to the character.
                print(f'  [gii_all_sites for {fn}: anion side unavailable, '
                      f'index is cation-only. {_note}]')
            cdev = (g['bvs'] - g['valence']).dropna().tolist()
            _gii_all[fn] = gii_all_sites(cdev, adev)
            _tick_ga.tick()
        _tick_ga.close()
    # v2.0.16: ONE DEFINITION. This column is computed here and must not
    # arrive already populated with something else. v2.0.15 wrote a different
    # quantity under this name in CELL 2 and this line silently overwrote it,
    # so the collision was invisible until someone read the CSV and found the
    # numbers were not the ones the changelog described.
    #
    # Comparing rather than merely testing presence, so re-running CELL 7 on
    # an already-enriched frame stays legal: what is forbidden is disagreement.
    _incoming = df['filename'].map(_gii_all)
    if 'gii_all_sites' in df.columns:
        _prev = pd.to_numeric(df['gii_all_sites'], errors='coerce')
        _new = pd.to_numeric(_incoming, errors='coerce')
        _both = _prev.notna() & _new.notna()
        if _both.any() and not np.allclose(_prev[_both], _new[_both],
                                           rtol=0, atol=1e-9):
            raise AssertionError(
                'gii_all_sites arrived already populated with different '
                'values. Two definitions of one column name; see v2.0.16.')
    df['gii_all_sites'] = _incoming

    # GII position within this run, since absolute thresholds are
    # family-dependent and 0.20 is only a rule of thumb
    _per_gii = df.groupby('filename')['gii'].first()
    _pct = _per_gii.rank(pct=True) * 100.0
    df['gii_percentile_in_run'] = df['filename'].map(_pct).round(1)

    # self-describing configuration
    df['cfg_cn_relative_cutoff'] = CN_RELATIVE_CUTOFF
    df['cfg_econ_regular_min'] = ECON_REGULAR_MIN
    df['cfg_radii_contact_base'] = IMPLAUSIBLE_CONTACT_FRACTION
    df['cfg_radii_cn_slope'] = RADII_CN_SLOPE
    df['cfg_anion_tolerance'] = ANION_TOLERANCE
    df['cfg_cation_gii_tolerance'] = CATION_GII_TOLERANCE
    df['cfg_gii_convention'] = 'cation_only'
    df['cfg_anion_anion_min_A'] = ANION_ANION_MIN
    df['cfg_cation_cation_min_A'] = CATION_CATION_MIN
    df['cfg_bv_sum_cutoff'] = BV_SUM_CUTOFF

    # ------------------------------------------------------------------
    # PGRM INTEGRITY GATES
    #
    # Applied HERE, before the CSV is written, so the file on disk and the
    # frame in memory carry the same columns. Classifying afterwards in the
    # calling cell would give a DataFrame with pgrm_* and a CSV without.
    #
    # Geometry decides severity before any chemistry is read. See
    # classify_pgrm for the four facets and for why the previous scheme -
    # which derived a tier FROM the bond valence sum - could not see the
    # dominant fault class in any family with positional freedom.
    # ------------------------------------------------------------------
    if 'classify_pgrm' in globals():
        df = classify_pgrm(df)
        df = apply_pgrm_suppression(df)
        if verbose:
            _st = df.drop_duplicates('filename')
            _t = _st['structure_pgrm_tier'].value_counts()
            print()
            print('  PGRM integrity gates')
            for _k in PGRM_TIERS:
                if _k in _t:
                    print(f'    {_k:14} {_t[_k]:6}  '
                          f'({100 * _t[_k] / len(_st):.1f}%)')
            _ex = _st[_st['structure_pgrm_tier'] == 'EXPUNGE']
            if len(_ex):
                print('    expunged for:',
                      dict(_ex['structure_pgrm_reason'].value_counts()))
                if not PGRM_SUPPRESS:
                    print('    PGRM_SUPPRESS is False, so their bond valence',
                          'results are still reported. Read pgrm_reason')
                    print('    before quoting any number from them.')
    else:
        print('  [classify_pgrm not defined; no integrity gates applied]')

    if output_csv_path is None:
        base, ext = os.path.splitext(batch_csv_path)
        output_csv_path = f"{base}_quality{ext}"
    df.to_csv(output_csv_path, index=False)

    if verbose:
        per = df.groupby('filename').first()
        # v2.0.24: elapsed, because a stage that took four minutes and a stage
        # that took forty seconds should not report themselves identically.
        print(f"\n  post-processing complete in "
              f"{_bat_hms(_time.perf_counter() - _t_pp)}")
        print(f"\nWritten: {output_csv_path}")
        n_imp = int((~per['structure_geometry_plausible'].astype(bool)).sum())
        print(f"  implausible-geometry structures: {n_imp} / {len(per)}")
        print(f"\n  bvs_diagnosis:")
        for k, v in df.groupby('filename').first()['bvs_diagnosis'].value_counts().items():
            print(f"    {k:28s} {v}")
        reg = df['polyhedron_regular'].dropna()
        if len(reg):
            print(f"\n  polyhedron_regular: {int(reg.sum())} / {len(reg)} sites")
    return df